//			// Update the row with the new values
//			// the was proposed for insertion.
//			sql.ResolveWithNewValues(),
//		).
//		// Override some of the fields with custom
//		// update values.
//		Update(func(u *ent.FreeOfferUpsert) {
//			SetIdentity(v+v).
//		}).
//		Exec(ctx)
func (_c *FreeOfferCreateBulk) OnConflict(opts ...sql.ConflictOption) *FreeOfferUpsertBulk {
	_c.conflict = opts
	return &FreeOfferUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
